<?php

if(PHP_SAPI!=='cli'){http_response_code(403);exit;}
$root=dirname(__DIR__);require_once $root.'/app/bootstrap.php';require_once $root.'/app/MigrationService.php';MigrationService::run();require_once $root.'/app/StorySimulationBatchService.php';$max=1;$choicesFile=null;foreach(array_slice($argv,1)as$arg){if(preg_match('/^--max=(\\d+)$/',$arg,$m))$max=max(1,min(100,(int)$m[1]));elseif(preg_match('/^--choices=(.+)$/',$arg,$m))$choicesFile=$m[1];}$choiceScript=null;if($choicesFile!==null){$raw=file_get_contents($choicesFile);if($raw===false){fwrite(STDERR,'Cannot read choice script file: '.$choicesFile.PHP_EOL);exit(2);}$decoded=json_decode($raw,true);if(!is_array($decoded)){fwrite(STDERR,'Choice script file is not valid JSON: '.$choicesFile.PHP_EOL);exit(2);}try{$choiceScript=SimulationHarness::normalizeChoiceScript($decoded);}catch(Throwable $e){fwrite(STDERR,'Invalid choice script: '.$e->getMessage().PHP_EOL);exit(2);}}$processed=0;try{while($processed<$max){$batch=StorySimulationBatchService::processNext($choiceScript);if(!$batch)break;$processed++;echo 'Batch '.$batch['simulation_review_batch_id'].': '.$batch['status'].' '.$batch['completed_runs'].'/'.$batch['requested_runs'].PHP_EOL;}echo 'Processed '.$processed.' simulation review run(s).'.PHP_EOL;exit(0);}catch(Throwable $e){fwrite(STDERR,'Simulation review worker failed: '.$e->getMessage().PHP_EOL);exit(1);}
